use crate::engine::module::*;
use crate::engine::params::Params;
use crate::modules::util::with_alpha;
use crate::theme::Branch;

const GOLD: [f32; 4] = [0.86, 0.62, 0.22, 1.0];
const GOLD_PALE: [f32; 4] = [0.98, 0.86, 0.55, 1.0];
const EMBER: [f32; 4] = [0.75, 0.30, 0.10, 1.0];
const LEIBNIZ_BLUE: [f32; 4] = [0.35, 0.62, 0.95, 1.0];
const AXIS: [f32; 4] = [0.42, 0.40, 0.34, 0.55];

/// Engraved warm-black graph paper for the 2D chambers.
const PAPER_SHADE: &str = r#"
fn shade(ndc: vec2<f32>, uv: vec2<f32>) -> vec4<f32> {
    let w = plane_pos(ndc);
    var color = vec3<f32>(0.016, 0.013, 0.010);
    let g1 = grid_glow(w, 0.75);
    let g2 = grid_glow(w * 4.0, 0.55);
    color += vec3<f32>(0.30, 0.22, 0.10) * g1 * 0.16;
    color += vec3<f32>(0.30, 0.22, 0.10) * g2 * 0.05;
    let vig = 1.0 - 0.35 * dot(ndc, ndc);
    return vec4<f32>(color * vig, 1.0);
}
"#;

/// The cathedral nave: god-rays, incense haze, and a warm void.
const CATHEDRAL_SHADE: &str = r#"
fn shade(ndc: vec2<f32>, uv: vec2<f32>) -> vec4<f32> {
    let t = U.res.z;
    // Vertical god-rays, slowly breathing.
    var ray = 0.0;
    let x = uv.x * 14.0;
    ray += sin(x * 1.0 + t * 0.10) * 0.5 + 0.5;
    ray += (sin(x * 2.7 - t * 0.07 + 1.7) * 0.5 + 0.5) * 0.6;
    ray = pow(ray / 1.6, 3.0);
    let updown = pow(1.0 - uv.y, 1.6);
    var color = vec3<f32>(0.012, 0.010, 0.009);
    color += vec3<f32>(0.32, 0.22, 0.09) * ray * updown * 0.30;
    // Dust motes.
    let cell = floor(uv * vec2<f32>(160.0, 90.0));
    let h = hash21(cell);
    let sparkle = step(0.9975, h) * (0.5 + 0.5 * sin(t * 2.0 + h * 40.0));
    color += vec3<f32>(0.8, 0.65, 0.35) * sparkle * 0.10 * updown;
    let vig = 1.0 - 0.45 * dot(ndc * vec2<f32>(0.8, 1.0), ndc * vec2<f32>(0.8, 1.0));
    return vec4<f32>(color * max(vig, 0.0), 1.0);
}
"#;

/// A fluent curve traced in the window x in [0,8]: position and two
/// derivatives with respect to the generation parameter s in [0,1].
#[derive(Clone, Copy)]
struct FluentState {
    x: f64,
    y: f64,
    dx: f64,
    dy: f64,
    ddx: f64,
    ddy: f64,
}

fn fluent(k: usize, s: f64) -> FluentState {
    match k {
        // Cycloid, two arches across the window: the Helen of geometers.
        0 => {
            let a = 8.0 / (4.0 * std::f64::consts::PI);
            let tau = s * 4.0 * std::f64::consts::PI;
            let dtau = 4.0 * std::f64::consts::PI;
            FluentState {
                x: a * (tau - tau.sin()),
                y: a * (1.0 - tau.cos()),
                dx: a * (1.0 - tau.cos()) * dtau,
                dy: a * tau.sin() * dtau,
                ddx: a * tau.sin() * dtau * dtau,
                ddy: a * tau.cos() * dtau * dtau,
            }
        }
        // Galilean parabola.
        1 => {
            let x = s * 8.0;
            FluentState {
                x,
                y: x * x / 16.0,
                dx: 8.0,
                dy: x,
                ddx: 0.0,
                ddy: 8.0,
            }
        }
        // Serpentine cubic.
        2 => {
            let x = s * 8.0;
            let u = x - 4.0;
            FluentState {
                x,
                y: u * u * u / 16.0 - u / 2.0 + 1.2,
                dx: 8.0,
                dy: (3.0 * u * u / 16.0 - 0.5) * 8.0,
                ddx: 0.0,
                ddy: (6.0 * u / 16.0) * 64.0 / 8.0,
            }
        }
        // Dying oscillation.
        3 => {
            let x = s * 8.0;
            let e = (-x / 5.0f64).exp();
            let (sn, cs) = (1.6 * x).sin_cos();
            FluentState {
                x,
                y: 1.2 + 1.6 * e * sn,
                dx: 8.0,
                dy: 1.6 * e * (1.6 * cs - sn / 5.0) * 8.0,
                ddx: 0.0,
                ddy: 1.6 * e * (sn * (1.0 / 25.0 - 2.56) - 2.0 * 1.6 * cs / 5.0) * 64.0,
            }
        }
        // Semicircular arch (exact quadrature: pi r^2 / 2).
        _ => {
            let th = s * std::f64::consts::PI;
            let r = 2.5;
            let dth = std::f64::consts::PI;
            FluentState {
                x: 4.0 - r * th.cos(),
                y: r * th.sin(),
                dx: r * th.sin() * dth,
                dy: r * th.cos() * dth,
                ddx: r * th.cos() * dth * dth,
                ddy: -r * th.sin() * dth * dth,
            }
        }
    }
}

const CURVE_NAMES: [&str; 5] = [
    "Cycloid",
    "Parabola",
    "Serpentine cubic",
    "Dying oscillation",
    "Semicircle",
];
const CURVE_EQNS: [&str; 5] = [
    "x = a(\u{03C4} \u{2212} sin \u{03C4}),   y = a(1 \u{2212} cos \u{03C4})",
    "y = x\u{00B2}/16",
    "y = (x\u{2212}4)\u{00B3}/16 \u{2212} (x\u{2212}4)/2 + 1.2",
    "y = 1.2 + 1.6\u{00B7}e^{\u{2212}x/5} sin 1.6x",
    "x\u{00B2} + y\u{00B2} = r\u{00B2}   (upper arch)",
];

const N_SAMPLES: usize = 320;

pub struct FluxionChamber {
    params: Params,
    area_mesh: Option<GpuMesh>,
    quad_mesh: Option<GpuMesh>,
    sector_mesh: Option<GpuMesh>,
    revolve_mesh: Option<GpuMesh>,
    s: f64,
    orbit_pos: (f64, f64),
    orbit_vel: (f64, f64),
    t_now: f64,
}

impl FluxionChamber {
    pub fn new() -> Self {
        let mut p = Params::new();
        p.choice("curve", "Fluent curve", "Symbolic", CURVE_NAMES.to_vec(), 0);
        p.toggle("tangent", "Tangent line", "Display", true);
        p.toggle("accel", "Second fluxion (acceleration)", "Display", false);
        p.slider("pulse", "Moment pulse rate", "Physics", 0.5, 4.0, 1.5, "/s");
        p.int("steps", "Leibniz differences", "Physics", 4, 48, 14);
        p.slider("ecc", "Orbit eccentricity", "Physics", 0.0, 0.85, 0.55, "");
        p.slider(
            "revs",
            "Revolution sweep",
            "Physics",
            0.2,
            2.0,
            0.8,
            "turns",
        );
        Self {
            params: p,
            area_mesh: None,
            quad_mesh: None,
            sector_mesh: None,
            revolve_mesh: None,
            s: 0.0,
            orbit_pos: (0.0, 0.0),
            orbit_vel: (0.0, 0.0),
            t_now: 0.0,
        }
    }

    fn k(&self) -> usize {
        self.params.c("curve")
    }

    /// Kepler ellipse position at mean anomaly fraction `f` in [0,1).
    fn kepler(&self, f: f64) -> (f64, f64) {
        let e = self.params.f("ecc");
        let a = 2.1;
        let m = f * std::f64::consts::TAU;
        let mut big_e = m;
        for _ in 0..12 {
            big_e -= (big_e - e * big_e.sin() - m) / (1.0 - e * big_e.cos());
        }
        let x = a * (big_e.cos() - e);
        let y = a * (1.0 - e * e).sqrt() * big_e.sin();
        (x, y)
    }

    fn area_under(&self, k: usize, s_max: f64) -> f64 {
        // Trapezoid accumulation of y dx along the curve.
        let n = 400;
        let mut acc = 0.0;
        let mut prev = fluent(k, 0.0);
        for i in 1..=n {
            let s = s_max * i as f64 / n as f64;
            let f = fluent(k, s);
            acc += 0.5 * (f.y + prev.y) * (f.x - prev.x);
            prev = f;
        }
        acc
    }
}

fn curve_points(k: usize, s0: f64, s1: f64, n: usize, lift: f32) -> Vec<Vec3> {
    (0..=n)
        .map(|i| {
            let s = s0 + (s1 - s0) * i as f64 / n as f64;
            let f = fluent(k, s);
            Vec3::new(f.x as f32, f.y as f32, lift)
        })
        .collect()
}

impl ConceptModule for FluxionChamber {
    fn info(&self) -> ModuleInfo {
        ModuleInfo {
            id: "newton.fluxions",
            name: "The Fluxion Chamber",
            tagline: "Quantities generated by motion",
            branch: Branch::Fluxions,
            description: "Newton did not build the calculus from static infinitesimals but from motion: a fluent is a quantity flowing in time, and its fluxion \u{1E8B} is the velocity with which it is generated. Here curves, areas, and solids are not drawn \u{2014} they are grown, and every tangent is a velocity.",
            epigraph: Some((
                "Mathematical quantities I consider not as consisting of least possible parts, but as described by continuous motion.",
                "Isaac Newton, De Quadratura Curvarum",
            )),
        }
    }

    fn modes(&self) -> Vec<RenderMode> {
        vec![
            RenderMode::plane("fluent", "Fluent Generation", "A moving point grows the curve; the sweeping ordinate grows the area", 3.0)
                .look_at(4.0, 1.4, 0.0),
            RenderMode::plane("fluxion", "Fluxion Vectors", "\u{1E8B}, \u{1E8F}: the instantaneous velocities of generation, resolved and composed", 3.0)
                .look_at(4.0, 1.4, 0.0),
            RenderMode::plane("moment", "Moment Pulse", "The moment o: an evanescent increment, magnified in the lens", 3.0)
                .look_at(4.0, 1.4, 0.0),
            RenderMode::plane("inverse", "Inverse Fluxion", "Quadrature: swept area beneath \u{1E8F} becomes the height of y", 3.4)
                .look_at(4.0, 0.4, 0.0),
            RenderMode::plane("split", "Newton \u{00B7} Leibniz", "One curve, two calculi: velocities of generation against ratios of differentials", 2.6)
                .look_at(4.0, 1.1, 0.0),
            RenderMode::plane("principia", "Principia Motion", "Kepler's second law: the radius sweeps equal areas in equal times", 3.2),
            RenderMode::orbit("solids", "Generation of Solids", "The curve revolves; a volume is generated by motion", 12.0, 0.42, 0.85)
                .look_at(4.0, 0.6, 0.0),
            RenderMode::orbit("cathedral", "Fluxion Cathedral", "Presentation: the cycloid choir under god-rays", 14.0, 0.18, 1.35)
                .look_at(4.0, 1.5, 0.0),
            RenderMode::plane("brach", "Brachistochrone Race", "Straight, circular, cycloid: the Bernoulli challenge, run live", 1.7)
                .look_at(1.5, -0.9, 0.0),
            RenderMode::plane("tauto", "Tautochrone Chorus", "Released from any height on a cycloid, all beads arrive together", 1.6)
                .look_at(0.0, 0.9, 0.0),
        ]
    }

    fn default_modes(&self) -> Vec<usize> {
        vec![0, 1]
    }

    fn params(&mut self) -> &mut Params {
        &mut self.params
    }
    fn params_ref(&self) -> &Params {
        &self.params
    }

    fn init(&mut self, gpu: &GpuContext, rend: &mut Renderers) {
        rend.register_field(gpu, "fluxion.paper", PAPER_SHADE, false);
        rend.register_field(gpu, "fluxion.cathedral", CATHEDRAL_SHADE, false);

        // Area fill under the fluent curve: strip of (curve, base) pairs.
        let make_strip = |n: usize| {
            let mut d = MeshData::new();
            for _ in 0..=n {
                d.vertices.push(MeshVertex {
                    pos: [0.0; 3],
                    normal: [0.0, 0.0, 1.0],
                    color: [1.0; 4],
                });
                d.vertices.push(MeshVertex {
                    pos: [0.0; 3],
                    normal: [0.0, 0.0, 1.0],
                    color: [1.0; 4],
                });
            }
            for i in 0..n as u32 {
                let a = i * 2;
                d.indices
                    .extend_from_slice(&[a, a + 1, a + 2, a + 2, a + 1, a + 3]);
            }
            d
        };
        let mut area = make_strip(N_SAMPLES).upload(gpu, &rend.mesh_bgl);
        area.set_model(gpu, glam::Mat4::IDENTITY, [1.0; 4], [1.0, 0.0, 1.0, 0.0]);
        self.area_mesh = Some(area);
        let mut quad = make_strip(N_SAMPLES).upload(gpu, &rend.mesh_bgl);
        quad.set_model(gpu, glam::Mat4::IDENTITY, [1.0; 4], [1.0, 0.0, 1.0, 0.0]);
        self.quad_mesh = Some(quad);

        // Kepler sectors: 12 fans of 16 triangles.
        let mut sect = MeshData::new();
        for _ in 0..12 {
            for _ in 0..17 {
                sect.vertices.push(MeshVertex {
                    pos: [0.0; 3],
                    normal: [0.0, 0.0, 1.0],
                    color: [1.0; 4],
                });
            }
            // focus vertex per sector at end
            sect.vertices.push(MeshVertex {
                pos: [0.0; 3],
                normal: [0.0, 0.0, 1.0],
                color: [1.0; 4],
            });
        }
        for sec in 0..12u32 {
            let base = sec * 18;
            let focus = base + 17;
            for i in 0..16 {
                sect.indices
                    .extend_from_slice(&[focus, base + i, base + i + 1]);
            }
        }
        let mut sm = sect.upload(gpu, &rend.mesh_bgl);
        sm.set_model(gpu, glam::Mat4::IDENTITY, [1.0; 4], [1.0, 0.0, 1.0, 0.0]);
        self.sector_mesh = Some(sm);

        // Surface of revolution: 96 x 64 grid, vertices rewritten per frame.
        let rev = MeshData::parametric(96, 64, |_, _| (Vec3::ZERO, [1.0; 4]));
        let mut rm = rev.upload(gpu, &rend.mesh_bgl);
        rm.set_model(gpu, glam::Mat4::IDENTITY, [1.0; 4], [0.0, 0.22, 0.92, 0.0]);
        self.revolve_mesh = Some(rm);
    }

    fn update(&mut self, gpu: &GpuContext, t: f64, _dt: f64) {
        self.t_now = t;
        self.s = (t / 12.0).clamp(0.0, 1.0) % 1.0;
        let k = self.k();
        let s = self.s.max(1e-4);

        // Area fill vertices (fluent mode).
        if let Some(m) = &self.area_mesh {
            let fill = with_alpha(GOLD, 0.16);
            let mut verts = Vec::with_capacity((N_SAMPLES + 1) * 2);
            for i in 0..=N_SAMPLES {
                let si = s * i as f64 / N_SAMPLES as f64;
                let f = fluent(k, si);
                verts.push(MeshVertex {
                    pos: [f.x as f32, f.y as f32, -0.05],
                    normal: [0.0, 0.0, 1.0],
                    color: fill,
                });
                verts.push(MeshVertex {
                    pos: [f.x as f32, 0.0, -0.05],
                    normal: [0.0, 0.0, 1.0],
                    color: fill,
                });
            }
            m.update_vertices(gpu, &verts);
        }

        // Quadrature fill: area under the fluxion curve (lower panel).
        if let Some(m) = &self.quad_mesh {
            let mut verts = Vec::with_capacity((N_SAMPLES + 1) * 2);
            for i in 0..=N_SAMPLES {
                let si = s * i as f64 / N_SAMPLES as f64;
                let f = fluent(k, si);
                let yv = (f.dy / f.dx.max(1e-6)) as f32; // dy/dx as the plotted fluxion
                let yy = -2.6 + yv * 0.55;
                let c = if yv >= 0.0 {
                    with_alpha(GOLD, 0.20)
                } else {
                    with_alpha(LEIBNIZ_BLUE, 0.20)
                };
                verts.push(MeshVertex {
                    pos: [f.x as f32, yy, -0.05],
                    normal: [0.0, 0.0, 1.0],
                    color: c,
                });
                verts.push(MeshVertex {
                    pos: [f.x as f32, -2.6, -0.05],
                    normal: [0.0, 0.0, 1.0],
                    color: c,
                });
            }
            m.update_vertices(gpu, &verts);
        }

        // Kepler equal-area sectors (12 equal-time wedges up to current time).
        if let Some(m) = &self.sector_mesh {
            let frac = self.s;
            let mut verts = Vec::with_capacity(12 * 18);
            for sec in 0..12 {
                let f0 = sec as f64 / 12.0;
                let f1 = (sec + 1) as f64 / 12.0;
                let vis = frac > f0;
                let f_end = f1.min(frac.max(f0));
                let alpha = if sec % 2 == 0 { 0.13 } else { 0.20 };
                let c = if vis {
                    with_alpha(GOLD, alpha)
                } else {
                    [0.0; 4]
                };
                for i in 0..17 {
                    let ff = f0 + (f_end - f0) * i as f64 / 16.0;
                    let (x, y) = self.kepler(ff);
                    verts.push(MeshVertex {
                        pos: [x as f32, y as f32, -0.05],
                        normal: [0.0, 0.0, 1.0],
                        color: c,
                    });
                }
                verts.push(MeshVertex {
                    pos: [0.0, 0.0, -0.05],
                    normal: [0.0, 0.0, 1.0],
                    color: c,
                });
            }
            m.update_vertices(gpu, &verts);
        }
        let (px, py) = self.kepler(self.s);
        let h = 1e-4;
        let (qx, qy) = self.kepler(self.s + h);
        self.orbit_pos = (px, py);
        self.orbit_vel = ((qx - px) / h / 12.0, (qy - py) / h / 12.0);

        // Surface of revolution about the x-axis, swept by angle.
        if let Some(m) = &self.revolve_mesh {
            let sweep = (self.params.f("revs") * std::f64::consts::TAU) * self.s;
            let mut verts = Vec::with_capacity(96 * 64);
            let du = 1.0 / 95.0;
            for i in 0..96 {
                let u = i as f64 * du;
                let f = fluent(k, u);
                let r = f.y.max(0.0);
                for j in 0..64 {
                    let v = j as f64 / 63.0;
                    let ang = sweep * v;
                    let y = r * ang.cos();
                    let z = r * ang.sin();
                    // Approximate normal: radial away from the x-axis, tilted by slope.
                    let slope = (f.dy / f.dx.max(1e-6)) as f32;
                    let nr =
                        Vec3::new(-slope, ang.cos() as f32, ang.sin() as f32).normalize_or_zero();
                    let glow = 0.30 + 0.32 * (v as f32);
                    let c = [GOLD[0] * glow, GOLD[1] * glow, GOLD[2] * glow, 1.0];
                    verts.push(MeshVertex {
                        pos: [f.x as f32, y as f32, z as f32],
                        normal: nr.to_array(),
                        color: c,
                    });
                }
            }
            m.update_vertices(gpu, &verts);
        }
    }

    fn render(&mut self, _gpu: &GpuContext, mode: usize, t: f64, _cam: &Camera, scene: &mut Scene) {
        let k = self.k();
        let s = self.s.max(1e-4);
        let f = fluent(k, s);
        let p = Vec3::new(f.x as f32, f.y as f32, 0.0);
        scene.clear = [0.010, 0.008, 0.007, 1.0];

        let draw_axes = |scene: &mut Scene| {
            scene.line(
                LineLayer::World,
                Vec3::new(-0.6, 0.0, -0.02),
                Vec3::new(8.6, 0.0, -0.02),
                1.4,
                AXIS,
            );
            scene.line(
                LineLayer::World,
                Vec3::new(0.0, -0.6, -0.02),
                Vec3::new(0.0, 3.6, -0.02),
                1.4,
                AXIS,
            );
        };

        match mode {
            // ------------------------------------------------ fluent generation
            0 => {
                scene.field = Some("fluxion.paper");
                draw_axes(scene);
                if let Some(m) = &self.area_mesh {
                    scene.mesh(m);
                }
                // Grown part of the curve: luminous; future part: ghost.
                let grown = curve_points(k, 0.0, s, 200, 0.0);
                let ghost = curve_points(k, s, 1.0, 200, 0.0);
                scene.polyline(LineLayer::World, &ghost, 1.0, with_alpha(GOLD, 0.10));
                scene.glow_polyline(&grown, 2.4, GOLD, 3.2);
                // The sweeping ordinate.
                scene.line_soft(
                    LineLayer::WorldAdd,
                    Vec3::new(p.x, 0.0, 0.0),
                    p,
                    3.0,
                    with_alpha(GOLD_PALE, 0.55),
                );
                scene.point(p, 5.0, GOLD_PALE, 2.0);
                scene.point(Vec3::new(p.x, 0.0, 0.0), 2.5, with_alpha(GOLD, 0.8), 1.0);
            }
            // ------------------------------------------------ fluxion vectors
            1 => {
                scene.field = Some("fluxion.paper");
                draw_axes(scene);
                let grown = curve_points(k, 0.0, 1.0, 320, 0.0);
                scene.glow_polyline(&grown, 1.8, with_alpha(GOLD, 0.75), 2.6);
                let vscale = 0.12f32;
                let v = Vec3::new(f.dx as f32, f.dy as f32, 0.0) * vscale;
                // Components: x-fluxion and y-fluxion.
                scene.vector(
                    p,
                    Vec3::new(v.x, 0.0, 0.0),
                    3.0,
                    with_alpha(GOLD_PALE, 0.65),
                );
                scene.vector(
                    p,
                    Vec3::new(0.0, v.y, 0.0),
                    3.0,
                    with_alpha(LEIBNIZ_BLUE, 0.65),
                );
                // The composed velocity of generation.
                scene.vector(p, v, 4.5, GOLD_PALE);
                // Parallelogram of composition.
                scene.line(
                    LineLayer::World,
                    p + Vec3::new(v.x, 0.0, 0.0),
                    p + v,
                    1.0,
                    with_alpha(GOLD_PALE, 0.25),
                );
                scene.line(
                    LineLayer::World,
                    p + Vec3::new(0.0, v.y, 0.0),
                    p + v,
                    1.0,
                    with_alpha(GOLD_PALE, 0.25),
                );
                if self.params.b("tangent") {
                    let dir = v.normalize_or_zero();
                    scene.line(
                        LineLayer::World,
                        p - dir * 30.0,
                        p + dir * 30.0,
                        1.0,
                        with_alpha(GOLD, 0.22),
                    );
                }
                if self.params.b("accel") {
                    let a = Vec3::new(f.ddx as f32, f.ddy as f32, 0.0) * vscale * vscale * 6.0;
                    scene.vector(p, a, 3.0, with_alpha(EMBER, 0.9));
                }
                scene.point(p, 5.0, GOLD_PALE, 2.0);
            }
            // ------------------------------------------------ moment pulse
            2 => {
                scene.field = Some("fluxion.paper");
                draw_axes(scene);
                let grown = curve_points(k, 0.0, 1.0, 320, 0.0);
                scene.glow_polyline(&grown, 1.8, with_alpha(GOLD, 0.7), 2.4);
                // Expanding moment rings at pulse epochs.
                let rate = self.params.f("pulse");
                let phase = t * rate;
                for ring in 0..3 {
                    let age = ((phase - ring as f64 * 0.33).fract() + 1.0) % 1.0;
                    let sp =
                        ((phase - ring as f64 * 0.33).floor() + ring as f64 * 0.33) / rate / 12.0;
                    if sp < 0.0 || sp > 1.0 {
                        continue;
                    }
                    let fp = fluent(k, sp.clamp(0.0, 1.0));
                    let cp = Vec3::new(fp.x as f32, fp.y as f32, 0.0);
                    let r = 0.05 + age as f32 * 0.55;
                    let fade = (1.0 - age as f32).powi(2) * 0.5;
                    let ringpts: Vec<Vec3> = (0..=48)
                        .map(|i| {
                            let a = i as f32 / 48.0 * std::f32::consts::TAU;
                            cp + Vec3::new(a.cos() * r, a.sin() * r, 0.02)
                        })
                        .collect();
                    scene.polyline(
                        LineLayer::WorldAdd,
                        &ringpts,
                        1.6,
                        with_alpha(GOLD_PALE, fade),
                    );
                }
                // The magnifying lens: characteristic triangle, enlarged.
                let o = 0.035; // the moment, exaggerated for sight
                let dx = (f.dx * o) as f32;
                let dy = (f.dy * o) as f32;
                let lens = Vec3::new(6.6, 3.1, 0.0);
                let mag = 14.0 / (dx * dx + dy * dy).sqrt().max(1e-4)
                    * (dx * dx + dy * dy).sqrt().max(1e-4);
                let _ = mag;
                let sc = 1.6 / (dx.abs().max(dy.abs()).max(1e-4));
                let a0 = lens + Vec3::new(-dx * sc * 0.5, -dy * sc * 0.5, 0.0);
                let a1 = a0 + Vec3::new(dx * sc, 0.0, 0.0);
                let a2 = a0 + Vec3::new(dx * sc, dy * sc, 0.0);
                scene.line(LineLayer::Overlay, a0, a1, 2.4, GOLD_PALE);
                scene.line(LineLayer::Overlay, a1, a2, 2.4, LEIBNIZ_BLUE);
                scene.line(LineLayer::Overlay, a2, a0, 2.4, with_alpha(GOLD, 0.9));
                // Lens ring.
                let ring: Vec<Vec3> = (0..=64)
                    .map(|i| {
                        let a = i as f32 / 64.0 * std::f32::consts::TAU;
                        lens + Vec3::new(a.cos() * 1.35, a.sin() * 1.35, 0.0)
                    })
                    .collect();
                scene.polyline(LineLayer::Overlay, &ring, 1.4, with_alpha(GOLD, 0.5));
                // Sight-line from point to lens.
                scene.line_soft(
                    LineLayer::Overlay,
                    p,
                    lens - Vec3::new(0.95, 0.95, 0.0),
                    1.6,
                    with_alpha(GOLD, 0.14),
                );
                // The true (unmagnified) moment at the point.
                scene.line(
                    LineLayer::World,
                    p,
                    p + Vec3::new(dx, 0.0, 0.0),
                    2.0,
                    GOLD_PALE,
                );
                scene.line(
                    LineLayer::World,
                    p + Vec3::new(dx, 0.0, 0.0),
                    p + Vec3::new(dx, dy, 0.0),
                    2.0,
                    LEIBNIZ_BLUE,
                );
                scene.point(p, 5.0, GOLD_PALE, 2.0);
            }
            // ------------------------------------------------ inverse fluxion
            3 => {
                scene.field = Some("fluxion.paper");
                // Upper panel: the fluent y(x) rising as accumulated area.
                scene.line(
                    LineLayer::World,
                    Vec3::new(-0.6, 0.0, -0.02),
                    Vec3::new(8.6, 0.0, -0.02),
                    1.2,
                    AXIS,
                );
                // Lower panel: the fluxion curve.
                scene.line(
                    LineLayer::World,
                    Vec3::new(-0.6, -2.6, -0.02),
                    Vec3::new(8.6, -2.6, -0.02),
                    1.2,
                    AXIS,
                );
                if let Some(m) = &self.quad_mesh {
                    scene.mesh(m);
                }
                // Fluxion curve (dy/dx over x), full ghost + tracked point.
                let fx_pts: Vec<Vec3> = (0..=320)
                    .map(|i| {
                        let si = i as f64 / 320.0;
                        let ff = fluent(k, si);
                        let yv = (ff.dy / ff.dx.max(1e-6)) as f32;
                        Vec3::new(ff.x as f32, -2.6 + yv * 0.55, 0.0)
                    })
                    .collect();
                scene.polyline(
                    LineLayer::World,
                    &fx_pts,
                    1.6,
                    with_alpha(LEIBNIZ_BLUE, 0.75),
                );
                // The fluent grows: y(x) = area so far (rescaled).
                let grown: Vec<Vec3> = (0..=160)
                    .map(|i| {
                        let si = s * i as f64 / 160.0;
                        let ff = fluent(k, si);
                        Vec3::new(ff.x as f32, ff.y as f32, 0.0)
                    })
                    .collect();
                scene.glow_polyline(&grown, 2.4, GOLD, 3.0);
                // Connecting ordinates: the bridge between the panels.
                let ff = fluent(k, s);
                let yv = (ff.dy / ff.dx.max(1e-6)) as f32;
                scene.line_soft(
                    LineLayer::WorldAdd,
                    Vec3::new(ff.x as f32, -2.6, 0.0),
                    Vec3::new(ff.x as f32, -2.6 + yv * 0.55, 0.0),
                    2.6,
                    with_alpha(LEIBNIZ_BLUE, 0.6),
                );
                scene.line_soft(
                    LineLayer::Overlay,
                    Vec3::new(ff.x as f32, -2.6 + yv * 0.55, 0.0),
                    Vec3::new(ff.x as f32, ff.y as f32, 0.0),
                    1.2,
                    with_alpha(GOLD_PALE, 0.20),
                );
                scene.point(
                    Vec3::new(ff.x as f32, ff.y as f32, 0.0),
                    4.5,
                    GOLD_PALE,
                    2.0,
                );
                scene.point(
                    Vec3::new(ff.x as f32, -2.6 + yv * 0.55, 0.0),
                    3.5,
                    LEIBNIZ_BLUE,
                    1.5,
                );
            }
            // ------------------------------------------------ Newton vs Leibniz
            4 => {
                scene.field = Some("fluxion.paper");
                let mid = 4.0f32;
                scene.line(
                    LineLayer::Overlay,
                    Vec3::new(mid, -1.8, 0.1),
                    Vec3::new(mid, 4.0, 0.1),
                    1.2,
                    with_alpha([0.5, 0.5, 0.6, 1.0], 0.35),
                );
                let squeeze = |pt: Vec3, side: f32| -> Vec3 {
                    // map x in [0,8] into left or right half
                    Vec3::new(side + pt.x * 0.44, pt.y * 0.85, pt.z)
                };
                let full: Vec<Vec3> = curve_points(k, 0.0, 1.0, 240, 0.0);
                // Newton side (left): motion.
                let nl: Vec<Vec3> = full.iter().map(|&q| squeeze(q, 0.15)).collect();
                let grown: Vec<Vec3> = curve_points(k, 0.0, s, 160, 0.0)
                    .iter()
                    .map(|&q| squeeze(q, 0.15))
                    .collect();
                scene.polyline(LineLayer::World, &nl, 1.0, with_alpha(GOLD, 0.15));
                scene.glow_polyline(&grown, 2.2, GOLD, 2.8);
                let pn = squeeze(p, 0.15);
                let v = Vec3::new(f.dx as f32 * 0.44, f.dy as f32 * 0.85, 0.0) * 0.10;
                scene.vector(pn, v, 4.0, GOLD_PALE);
                scene.point(pn, 4.5, GOLD_PALE, 2.0);
                // Leibniz side (right): the static staircase of differences.
                let ll: Vec<Vec3> = full.iter().map(|&q| squeeze(q, 4.35)).collect();
                scene.polyline(LineLayer::World, &ll, 1.6, with_alpha(LEIBNIZ_BLUE, 0.8));
                let n_steps = self.params.i("steps") as usize;
                let mut nearest = 0usize;
                let mut best = f64::MAX;
                for i in 0..n_steps {
                    let s0 = i as f64 / n_steps as f64;
                    let s1 = (i + 1) as f64 / n_steps as f64;
                    let f0 = fluent(k, s0);
                    let f1 = fluent(k, s1);
                    let q0 = squeeze(Vec3::new(f0.x as f32, f0.y as f32, 0.0), 4.35);
                    let q1 = squeeze(Vec3::new(f1.x as f32, f1.y as f32, 0.0), 4.35);
                    let hcol = with_alpha(LEIBNIZ_BLUE, 0.55);
                    scene.line(LineLayer::World, q0, Vec3::new(q1.x, q0.y, 0.0), 1.6, hcol);
                    scene.line(
                        LineLayer::World,
                        Vec3::new(q1.x, q0.y, 0.0),
                        q1,
                        1.6,
                        with_alpha(GOLD_PALE, 0.55),
                    );
                    if (s0 - s).abs() < best {
                        best = (s0 - s).abs();
                        nearest = i;
                    }
                }
                // Highlight the differential triangle nearest the moving point.
                {
                    let s0 = nearest as f64 / n_steps as f64;
                    let s1 = (nearest + 1) as f64 / n_steps as f64;
                    let f0 = fluent(k, s0);
                    let f1 = fluent(k, s1);
                    let q0 = squeeze(Vec3::new(f0.x as f32, f0.y as f32, 0.0), 4.35);
                    let q1 = squeeze(Vec3::new(f1.x as f32, f1.y as f32, 0.0), 4.35);
                    scene.line(
                        LineLayer::WorldAdd,
                        q0,
                        Vec3::new(q1.x, q0.y, 0.0),
                        3.0,
                        GOLD_PALE,
                    );
                    scene.line(
                        LineLayer::WorldAdd,
                        Vec3::new(q1.x, q0.y, 0.0),
                        q1,
                        3.0,
                        LEIBNIZ_BLUE,
                    );
                    scene.line(
                        LineLayer::WorldAdd,
                        q0,
                        q1,
                        2.0,
                        with_alpha([0.9, 0.9, 0.95, 1.0], 0.8),
                    );
                }
            }
            // ------------------------------------------------ Principia motion
            5 => {
                scene.clear = [0.006, 0.006, 0.010, 1.0];
                if let Some(m) = &self.sector_mesh {
                    scene.mesh(m);
                }
                // The ellipse.
                let orbit: Vec<Vec3> = (0..=256)
                    .map(|i| {
                        let (x, y) = self.kepler(i as f64 / 256.0);
                        Vec3::new(x as f32, y as f32, 0.0)
                    })
                    .collect();
                scene.polyline(LineLayer::World, &orbit, 1.3, with_alpha(GOLD, 0.35));
                let (px, py) = self.orbit_pos;
                let pp = Vec3::new(px as f32, py as f32, 0.0);
                // Radius vector.
                scene.line_soft(
                    LineLayer::WorldAdd,
                    Vec3::ZERO,
                    pp,
                    2.2,
                    with_alpha(GOLD_PALE, 0.4),
                );
                // Velocity and central force.
                let vv = Vec3::new(self.orbit_vel.0 as f32, self.orbit_vel.1 as f32, 0.0) * 0.55;
                scene.vector(pp, vv, 4.0, GOLD_PALE);
                let r2 = (px * px + py * py).max(1e-4);
                let fmag = (1.2 / r2).min(3.0) as f32;
                let fdir = -pp.normalize_or_zero() * fmag * 0.7;
                scene.vector(pp, fdir, 3.2, with_alpha(EMBER, 0.95));
                // The Sun.
                scene.point(Vec3::ZERO, 10.0, [1.0, 0.75, 0.30, 1.0], 3.0);
                scene.point(Vec3::ZERO, 4.0, [1.0, 0.95, 0.8, 1.0], 1.0);
                // The wanderer.
                scene.point(pp, 5.0, [0.85, 0.92, 1.0, 1.0], 2.0);
                // Second focus, engraved.
                let e = self.params.f("ecc");
                scene.point(
                    Vec3::new((-2.0 * 2.1 * e) as f32, 0.0, 0.0),
                    2.0,
                    with_alpha(AXIS, 0.8),
                    0.5,
                );
            }
            // ------------------------------------------------ solids of revolution
            6 => {
                scene.clear = [0.008, 0.007, 0.006, 1.0];
                if let Some(m) = &self.revolve_mesh {
                    scene.mesh(m);
                }
                // Generating curve, luminous, at angle 0.
                let grown = curve_points(k, 0.0, 1.0, 240, 0.0);
                scene.glow_polyline(&grown, 2.2, GOLD_PALE, 2.6);
                // Axis of revolution.
                scene.line(
                    LineLayer::World,
                    Vec3::new(-0.8, 0.0, 0.0),
                    Vec3::new(8.8, 0.0, 0.0),
                    1.6,
                    AXIS,
                );
                // Leading edge of the sweep.
                let sweep = (self.params.f("revs") * std::f64::consts::TAU) * s;
                let edge: Vec<Vec3> = (0..=240)
                    .map(|i| {
                        let u = i as f64 / 240.0;
                        let ff = fluent(k, u);
                        let r = ff.y.max(0.0);
                        Vec3::new(
                            ff.x as f32,
                            (r * sweep.cos()) as f32,
                            (r * sweep.sin()) as f32,
                        )
                    })
                    .collect();
                scene.glow_polyline(&edge, 2.0, GOLD, 2.6);
            }
            // ------------------------------------------------ brachistochrone
            8 => {
                scene.field = Some("fluxion.paper");
                // Three tracks from A(0,0) to B(pi*a, -2a), a = 0.75.
                let a = 0.75f64;
                let bx = std::f64::consts::PI * a;
                let by = -2.0 * a;
                let tracks: Vec<Vec<glam::Vec2>> = vec![
                    // Straight chute.
                    (0..=160)
                        .map(|i| {
                            let u = i as f64 / 160.0;
                            glam::Vec2::new((u * bx) as f32, (u * by) as f32)
                        })
                        .collect(),
                    // Circular arc sagging beneath the chord.
                    (0..=160)
                        .map(|i| {
                            let u = i as f64 / 160.0;
                            let sag = (u * std::f64::consts::PI).sin() * 0.62;
                            glam::Vec2::new((u * bx) as f32, (u * by - sag) as f32)
                        })
                        .collect(),
                    // The cycloid.
                    (0..=160)
                        .map(|i| {
                            let th = i as f64 / 160.0 * std::f64::consts::PI;
                            glam::Vec2::new(
                                (a * (th - th.sin())) as f32,
                                (-a * (1.0 - th.cos())) as f32,
                            )
                        })
                        .collect(),
                ];
                let cols = [
                    with_alpha(LEIBNIZ_BLUE, 0.85),
                    with_alpha(EMBER, 0.9),
                    GOLD_PALE,
                ];
                // Race clock restarts every 6 s.
                let race_t = t % 6.0;
                for (ti, track) in tracks.iter().enumerate() {
                    let pts: Vec<Vec3> = track.iter().map(|p| Vec3::new(p.x, p.y, 0.0)).collect();
                    scene.polyline(LineLayer::World, &pts, 1.8, cols[ti]);
                    // Bead: advance arclength by v = sqrt(2 g drop), g = 1.4.
                    let mut s_pos = 0usize;
                    let mut clock = 0.0f64;
                    for i in 1..track.len() {
                        let drop = (-track[i].y.min(track[i - 1].y)) as f64;
                        let v = (2.0 * 1.4 * drop.max(1e-4)).sqrt();
                        let ds = (track[i] - track[i - 1]).length() as f64;
                        clock += ds / v;
                        if clock > race_t {
                            break;
                        }
                        s_pos = i;
                    }
                    let p = track[s_pos];
                    scene.point(Vec3::new(p.x, p.y, 0.02), 6.0, cols[ti], 2.2);
                }
                scene.point(Vec3::new(0.0, 0.0, 0.02), 3.0, [0.9, 0.92, 0.98, 1.0], 1.4);
                scene.point(
                    Vec3::new(bx as f32, by as f32, 0.02),
                    3.0,
                    [0.9, 0.92, 0.98, 1.0],
                    1.4,
                );
            }
            // ------------------------------------------------ tautochrone
            9 => {
                scene.field = Some("fluxion.paper");
                let a = 0.62f64;
                // Cycloid bowl: x = a(th + sin th), y = a(1 - cos th), th in [-pi, pi].
                let bowl: Vec<Vec3> = (0..=200)
                    .map(|i| {
                        let th =
                            -std::f64::consts::PI + 2.0 * std::f64::consts::PI * i as f64 / 200.0;
                        Vec3::new(
                            (a * (th + th.sin())) as f32,
                            (a * (1.0 - th.cos())) as f32,
                            0.0,
                        )
                    })
                    .collect();
                scene.glow_polyline(&bowl, 2.2, GOLD, 2.8);
                // Exact SHM in arclength: s(t) = s0 cos(w t), w = sqrt(g/4a).
                let w = (1.4f64 / (4.0 * a)).sqrt();
                let phase = (w * t).cos();
                for k in 0..6 {
                    let s0 = (0.25 + 0.15 * k as f64) * 4.0 * a;
                    let s = s0 * phase;
                    let th = 2.0 * (s / (4.0 * a)).clamp(-1.0, 1.0).asin();
                    let p = Vec3::new(
                        (a * (th + th.sin())) as f32,
                        (a * (1.0 - th.cos())) as f32,
                        0.02,
                    );
                    let hue = crate::modules::util::phase_color(k as f32 * 0.9);
                    scene.point(p, 5.5, hue, 2.2);
                }
                // The meeting point.
                scene.point(
                    Vec3::new(0.0, 0.0, 0.01),
                    3.0,
                    with_alpha(GOLD_PALE, 0.8),
                    1.5,
                );
            }
            // ------------------------------------------------ the cathedral
            _ => {
                scene.field = Some("fluxion.cathedral");
                scene.clear = [0.008, 0.007, 0.006, 1.0];
                let a = 8.0 / (4.0 * std::f64::consts::PI);
                let tau_max = 4.0 * std::f64::consts::PI;
                let tau_p = s * tau_max;
                // Floor lattice, receding.
                for i in -6..=6 {
                    let z = i as f32 * 1.4;
                    scene.line(
                        LineLayer::World,
                        Vec3::new(-2.0, 0.0, z),
                        Vec3::new(10.0, 0.0, z),
                        0.8,
                        with_alpha(GOLD, 0.07),
                    );
                }
                for i in 0..=12 {
                    let x = -2.0 + i as f32;
                    scene.line(
                        LineLayer::World,
                        Vec3::new(x, 0.0, -8.4),
                        Vec3::new(x, 0.0, 8.4),
                        0.8,
                        with_alpha(GOLD, 0.05),
                    );
                }
                // Columns at the arch feet.
                for kx in 0..=2 {
                    let x = (kx as f64 * 2.0 * std::f64::consts::PI * a) as f32;
                    for zz in [-4.2f32, 4.2] {
                        scene.line_soft(
                            LineLayer::WorldAdd,
                            Vec3::new(x, 0.0, zz),
                            Vec3::new(x, 4.6, zz),
                            5.0,
                            with_alpha(GOLD, 0.16),
                        );
                        scene.point(Vec3::new(x, 4.6, zz), 4.0, with_alpha(GOLD_PALE, 0.5), 2.5);
                    }
                }
                // The cycloid choir: phase-shifted echoes in depth.
                for (echo, zc) in [(-2i32, -4.2f32), (-1, -2.1), (0, 0.0), (1, 2.1), (2, 4.2)] {
                    let alpha = if echo == 0 {
                        1.0
                    } else {
                        0.30 / echo.abs() as f32
                    };
                    let pts: Vec<Vec3> = (0..=320)
                        .map(|i| {
                            let tau = (i as f64 / 320.0) * tau_max;
                            Vec3::new(
                                (a * (tau - tau.sin())) as f32,
                                (a * (1.0 - tau.cos())) as f32 * 2.2,
                                zc,
                            )
                        })
                        .collect();
                    if echo == 0 {
                        let n_gr = ((s * 320.0) as usize).max(2);
                        scene.glow_polyline(&pts[..n_gr], 3.0, GOLD, 3.4);
                        scene.polyline(
                            LineLayer::World,
                            &pts[n_gr.saturating_sub(1)..],
                            1.0,
                            with_alpha(GOLD, 0.10),
                        );
                    } else {
                        scene.polyline(
                            LineLayer::WorldAdd,
                            &pts,
                            1.4,
                            with_alpha(GOLD, 0.10 * alpha + 0.04),
                        );
                    }
                }
                // The rolling wheel that generates the central cycloid.
                let cx = (a * tau_p) as f32;
                let cy = (a * 2.2) as f32;
                let wheel: Vec<Vec3> = (0..=72)
                    .map(|i| {
                        let ang = i as f32 / 72.0 * std::f32::consts::TAU;
                        Vec3::new(
                            cx + ang.cos() * a as f32,
                            cy + ang.sin() * (a * 2.2) as f32 * 0.4545 + 0.0,
                            0.0,
                        )
                    })
                    .collect();
                let _ = wheel;
                // (true rolling circle, radius a, scaled in y with the arch)
                let wheel2: Vec<Vec3> = (0..=72)
                    .map(|i| {
                        let ang = i as f64 / 72.0 * std::f64::consts::TAU;
                        Vec3::new(
                            (a * tau_p + a * ang.cos()) as f32,
                            ((a + a * ang.sin()) * 2.2) as f32,
                            0.0,
                        )
                    })
                    .collect();
                scene.polyline(
                    LineLayer::WorldAdd,
                    &wheel2,
                    1.6,
                    with_alpha(GOLD_PALE, 0.4),
                );
                // Spoke to the tracing point.
                let trace = Vec3::new(
                    (a * (tau_p - tau_p.sin())) as f32,
                    (a * (1.0 - tau_p.cos()) * 2.2) as f32,
                    0.0,
                );
                let hub = Vec3::new((a * tau_p) as f32, (a * 2.2) as f32, 0.0);
                scene.line(
                    LineLayer::WorldAdd,
                    hub,
                    trace,
                    1.8,
                    with_alpha(GOLD_PALE, 0.6),
                );
                scene.point(trace, 6.0, GOLD_PALE, 2.5);
                scene.point(hub, 2.5, with_alpha(GOLD, 0.7), 1.0);
                // Reflection below the floor.
                let refl: Vec<Vec3> = (0..=320)
                    .map(|i| {
                        let tau = (i as f64 / 320.0) * tau_max;
                        Vec3::new(
                            (a * (tau - tau.sin())) as f32,
                            -(a * (1.0 - tau.cos()) * 2.2) as f32 * 0.6,
                            0.0,
                        )
                    })
                    .collect();
                scene.polyline(LineLayer::World, &refl, 1.6, with_alpha(GOLD, 0.06));
            }
        }
        let _ = t;
    }

    fn inspector(&self, _t: f64) -> Vec<InsLine> {
        let k = self.k();
        let s = self.s.max(1e-4);
        let f = fluent(k, s);
        let slope = f.dy / f.dx.max(1e-9);
        let area = self.area_under(k, s);
        let mut v = vec![
            title("Fluents & Fluxions"),
            formula(CURVE_EQNS[k]),
            def("fluents:   x(t), y(t) \u{2014} quantities generated by flow"),
            ftex(
                "fluxion.def",
                "fluxions:  \u{1E8B} = dx/dt,  \u{1E8F} = dy/dt",
            ),
            def("moments:  \u{1E8B}o, \u{1E8F}o \u{2014} increments in the evanescent instant o"),
            ftex(
                "fluxion.slope",
                "slope = \u{1E8F}/\u{1E8B}        area A: \u{1E86} = y\u{00B7}\u{1E8B}",
            ),
            value(format!("s = {:.3}   x = {:.3}   y = {:.3}", s, f.x, f.y)),
            value(format!(
                "\u{1E8B} = {:.3}   \u{1E8F} = {:.3}   \u{1E8F}/\u{1E8B} = {}",
                f.dx,
                f.dy,
                if slope.abs() > 999.0 {
                    "\u{221E}".to_string()
                } else {
                    format!("{:.3}", slope)
                }
            )),
            value(format!("A(s) = \u{222B} y dx = {:.4}", area)),
        ];
        if k == 0 {
            v.push(note("Cycloid: slope \u{1E8F}/\u{1E8B} = cot(\u{03C4}/2). Area under one arch = 3\u{03C0}a\u{00B2} \u{2014} thrice the rolling circle, as Newton knew."));
        }
        v.push(note("Newton, Principia, Lemma II: \u{201C}Moments, as soon as they are of finite magnitude, cease to be moments.\u{201D}"));
        v
    }

    fn approx(&self, mode: usize) -> Option<&'static str> {
        match mode {
            0 | 3 => Some("Area by trapezoid accumulation (400 steps); curve exact analytic."),
            5 => Some("Orbit from the exact Kepler solution (Newton iteration, 12 steps); force arrow \u{221D} 1/r\u{00B2}."),
            6 => Some("Surface swept on a 96\u{00D7}64 lattice; profile exact analytic."),
            7 => Some("Presentation mode: geometry exact, vertical scale \u{00D7}2.2, lighting artistic."),
            _ => None,
        }
    }

    fn overlay(
        &self,
        painter: &egui::Painter,
        rect: egui::Rect,
        cam: &Camera,
        mode: usize,
        _t: f64,
    ) {
        let k = self.k();
        let s = self.s.max(1e-4);
        let f = fluent(k, s);
        let p = Vec3::new(f.x as f32, f.y as f32, 0.0);
        let gold = egui::Color32::from_rgb(230, 190, 110);
        let blue = egui::Color32::from_rgb(120, 170, 235);
        match mode {
            1 => {
                let vscale = 0.12f32;
                if let Some(sp) = to_screen(
                    cam,
                    rect,
                    p + Vec3::new(f.dx as f32 * vscale + 0.15, 0.0, 0.0),
                ) {
                    painter.text(
                        sp,
                        egui::Align2::LEFT_CENTER,
                        "\u{1E8B}",
                        crate::theme::math_font(16.0),
                        gold,
                    );
                }
                if let Some(sp) = to_screen(
                    cam,
                    rect,
                    p + Vec3::new(0.0, f.dy as f32 * vscale + 0.18, 0.0),
                ) {
                    painter.text(
                        sp,
                        egui::Align2::CENTER_BOTTOM,
                        "\u{1E8F}",
                        crate::theme::math_font(16.0),
                        blue,
                    );
                }
            }
            2 => {
                if let Some(sp) = to_screen(cam, rect, Vec3::new(6.6, 4.6, 0.0)) {
                    painter.text(
                        sp,
                        egui::Align2::CENTER_BOTTOM,
                        "the moment, magnified",
                        egui::FontId::proportional(10.5),
                        crate::theme::OVERLAY_DIM,
                    );
                }
                if let Some(sp) = to_screen(cam, rect, Vec3::new(6.6, 3.1, 0.0)) {
                    painter.text(
                        sp + egui::vec2(0.0, 30.0),
                        egui::Align2::CENTER_TOP,
                        "\u{1E8B}o",
                        crate::theme::math_font(13.0),
                        gold,
                    );
                    painter.text(
                        sp + egui::vec2(46.0, -8.0),
                        egui::Align2::LEFT_CENTER,
                        "\u{1E8F}o",
                        crate::theme::math_font(13.0),
                        blue,
                    );
                }
            }
            3 => {
                if let Some(sp) = to_screen(cam, rect, Vec3::new(0.3, 3.0, 0.0)) {
                    painter.text(
                        sp,
                        egui::Align2::LEFT_CENTER,
                        "fluent  y(x)",
                        crate::theme::math_font(13.0),
                        gold,
                    );
                }
                if let Some(sp) = to_screen(cam, rect, Vec3::new(0.3, -1.0, 0.0)) {
                    painter.text(
                        sp,
                        egui::Align2::LEFT_CENTER,
                        "fluxion  \u{1E8F}/\u{1E8B}",
                        crate::theme::math_font(13.0),
                        blue,
                    );
                }
            }
            4 => {
                if let Some(sp) = to_screen(cam, rect, Vec3::new(1.8, 3.6, 0.0)) {
                    painter.text(
                        sp,
                        egui::Align2::CENTER_CENTER,
                        "NEWTON \u{2014} \u{1E8B}, \u{1E8F}",
                        crate::theme::heading_font(15.0),
                        gold,
                    );
                    painter.text(
                        sp + egui::vec2(0.0, 16.0),
                        egui::Align2::CENTER_CENTER,
                        "velocities of generation",
                        egui::FontId::proportional(9.5),
                        crate::theme::OVERLAY_DIM,
                    );
                }
                if let Some(sp) = to_screen(cam, rect, Vec3::new(6.2, 3.6, 0.0)) {
                    painter.text(
                        sp,
                        egui::Align2::CENTER_CENTER,
                        "LEIBNIZ \u{2014} dx, dy",
                        crate::theme::heading_font(15.0),
                        blue,
                    );
                    painter.text(
                        sp + egui::vec2(0.0, 16.0),
                        egui::Align2::CENTER_CENTER,
                        "ratios of vanishing differences",
                        egui::FontId::proportional(9.5),
                        crate::theme::OVERLAY_DIM,
                    );
                }
            }
            5 => {
                if let Some(sp) = to_screen(cam, rect, Vec3::new(0.0, -0.35, 0.0)) {
                    painter.text(
                        sp,
                        egui::Align2::CENTER_TOP,
                        "Sol",
                        crate::theme::heading_font(12.0),
                        gold,
                    );
                }
            }
            7 => {
                if let Some(sp) = to_screen(cam, rect, Vec3::new(4.0, 5.6, 0.0)) {
                    painter.text(
                        sp,
                        egui::Align2::CENTER_CENTER,
                        "\u{1E8B}   \u{1E8F}   \u{1E8D}",
                        crate::theme::math_font(22.0),
                        gold.gamma_multiply(0.8),
                    );
                }
            }
            _ => {}
        }
    }
}
